-- ============================================================================
-- SEED60 - bộ dữ liệu mock 60 ngày cho VeggieLife (SQL Server). SINH TỰ ĐỘNG bởi generate_seed60.py (seed=60)
-- Dải ID 10001+; email @seed60.veggielife.vn; chạy lại nhiều lần an toàn (xóa theo dải ID rồi nạp lại).
-- LƯU Ý: dọn dẹp xóa MỌI dòng có ID >= 10001 ở các bảng trên (kể cả dòng app tạo sau khi nạp seed).
-- File lưu UTF-8: chạy bằng sqlcmd cần cờ -f 65001.
-- ============================================================================
SET NOCOUNT ON;
SET XACT_ABORT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
DECLARE @Now DATETIME2(7) = GETUTCDATE();
DECLARE @Dow0 INT = DATEDIFF(DAY, '19000101', CAST(@Now AS DATE)) % 7;   -- 0 = thứ Hai
PRINT N'>> SEED60 bắt đầu lúc ' + CONVERT(NVARCHAR(30), @Now, 121) + N' (UTC)';
BEGIN TRANSACTION;

PRINT N'>> [1/3] Dọn dữ liệu seed cũ (Level 2 -> Level 1, dải ID 10001-99999; user theo email seed)...';
DELETE FROM dbo.MealSlotSwapHistories WHERE Swap_History_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.ShoppingListItems WHERE Item_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.ShoppingLists WHERE List_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.MealSlots WHERE Slot_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.MealPlans WHERE Plan_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.ViolationReports WHERE Report_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.Votes WHERE Vote_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.Comments WHERE Comment_ID BETWEEN 10001 AND 99999 AND Parent_Comment_ID IS NOT NULL;
DELETE FROM dbo.Comments WHERE Comment_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.VideoTranscripts WHERE Transcript_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.Videos WHERE Video_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.Posts WHERE Post_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.Surveys WHERE Survey_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.ChatMessages WHERE Message_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.ChatSessions WHERE Chat_Session_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.AIQuotaLogs WHERE Log_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.UserScanHistory WHERE Scan_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.FridgeInventory WHERE Inventory_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.FridgeSessions WHERE Session_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.Product_ENumbers WHERE Product_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.ProductAllergens WHERE Product_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.Products WHERE Product_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.VenueCategories WHERE Venue_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.VeganVenues WHERE Venue_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.RecipeIngredients WHERE Recipe_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.Recipes WHERE Recipe_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.Foods WHERE Food_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.IngredientAllergens WHERE Ingredient_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.Ingredients WHERE Ingredient_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.PaymentTransactions WHERE Transaction_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.UserAllergies WHERE User_ID IN (SELECT User_ID FROM dbo.Users WHERE Email LIKE N'%@seed60.veggielife.vn');
DELETE FROM dbo.UserWeightHistory WHERE Log_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.HealthProfiles WHERE User_ID IN (SELECT User_ID FROM dbo.Users WHERE Email LIKE N'%@seed60.veggielife.vn');
DELETE FROM dbo.AuditLogs WHERE Audit_ID BETWEEN 10001 AND 99999;
DELETE FROM dbo.Users WHERE User_ID IN (SELECT User_ID FROM dbo.Users WHERE Email LIKE N'%@seed60.veggielife.vn');
PRINT N'   dọn xong.';

PRINT N'>> [2/3] Tra cứu dữ liệu master theo tên/mã...';
SELECT Dietary_School_ID, School_Code INTO #sch FROM dbo.DietarySchools;
SELECT Category_ID, Category_Name INTO #cat FROM dbo.FoodCategories;
SELECT Allergen_ID, Code INTO #alg FROM dbo.Allergens;
SELECT Duration_Days, MIN(Plan_ID) AS Plan_ID, MAX(Price) AS Price INTO #plan FROM dbo.SubscriptionPlans WHERE Duration_Days IN (30, 90, 365) GROUP BY Duration_Days;
IF (SELECT COUNT(*) FROM #sch) < 7   THROW 50010, N'Thiếu DietarySchools - hãy chạy seed master (01..08) trước.', 1;
IF (SELECT COUNT(*) FROM #cat) < 14  THROW 50011, N'Thiếu FoodCategories - hãy chạy seed master trước.', 1;
IF (SELECT COUNT(*) FROM #alg) < 10  THROW 50012, N'Thiếu Allergens - hãy chạy seed master trước.', 1;
IF (SELECT COUNT(*) FROM #plan) < 3  THROW 50013, N'Thiếu SubscriptionPlans 30/90/365 ngày - hãy chạy 08_Seed_SubscriptionPlans.sql trước.', 1;
IF (SELECT COUNT(*) FROM dbo.Ingredients WHERE Ingredient_ID < 10001) < 100 THROW 50014, N'Thiếu Ingredients master - hãy chạy 04_Seed_Ingredients.sql trước.', 1;

