) AS x(id, catnm, nm, img, cr)
JOIN #cat c ON c.Category_Name = x.catnm;
SELECT id, Category_ID, nm, img, cr FROM #foodsrc x WHERE NOT EXISTS (SELECT 1 FROM dbo.Foods e WHERE e.Food_Name = x.nm);
SET IDENTITY_INSERT dbo.Foods OFF;
UPDATE e SET e.Image_URL = x.img FROM dbo.Foods e JOIN #foodsrc x ON x.nm = e.Food_Name WHERE e.Image_URL IS NULL AND x.img IS NOT NULL;
DROP TABLE #foodsrc;
SELECT Food_ID, Food_Name INTO #food FROM dbo.Foods;
PRINT N'   + Foods (món ăn khái niệm từ sách): 69';
SET IDENTITY_INSERT dbo.Recipes ON;
