JOIN #ing i ON i.Ingredient_Name = v.nm;
IF @@ROWCOUNT <> 231 THROW 50001, N'FridgeInventory: tra cứu dữ liệu master thất bại (thiếu tên/mã)', 1;
SET IDENTITY_INSERT dbo.FridgeInventory OFF;
PRINT N'   + FridgeInventory: 531 dòng';
SET IDENTITY_INSERT dbo.UserScanHistory ON;
SET IDENTITY_INSERT dbo.UserScanHistory OFF;
PRINT N'   + UserScanHistory: 750 dòng';

SET IDENTITY_INSERT dbo.ChatSessions ON;
SET IDENTITY_INSERT dbo.ChatSessions OFF;
PRINT N'   + ChatSessions: 240 dòng';
SET IDENTITY_INSERT dbo.ChatMessages ON;
SET IDENTITY_INSERT dbo.ChatMessages OFF;
PRINT N'   + ChatMessages: 2236 dòng';
