(10339, 10036, 'USER', N'Mình ăn chay thì nên bổ sung đạm từ nguồn nào?', NULL, DATEADD(MINUTE,-13450,@Now)),
(10340, 10036, 'ASSISTANT', N'Bạn có thể lấy đạm từ đậu hũ, tempeh, các loại đậu (đậu nành, đậu lăng, đậu gà), hạt và ngũ cốc nguyên hạt. Kết hợp nhiều nguồn trong ngày giúp đủ các axit amin cần thiết. Gợi ý thêm: Rau Củ Xào Thập Cẩm.', N'{"sources":[{"type":"RECIPE","id":10044,"title":"Rau Củ Xào Thập Cẩm – bản giảm cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10044,"title":"Rau Củ Xào Thập Cẩm – bản giảm cân","cookTimeMinutes":29}]}', DATEADD(MINUTE,-13449,@Now)),
(10341, 10037, 'USER', N'Gợi ý thực đơn giảm cân cho một ngày ăn chay?', NULL, DATEADD(MINUTE,-81611,@Now)),
(10342, 10037, 'ASSISTANT', N'Bạn có thể ăn sáng với cháo yến mạch rau củ, trưa với cơm gạo lứt và đậu hũ sốt cà chua, tối với canh nấm rau củ. Tổng năng lượng nên bám theo mục tiêu calo trong hồ sơ của bạn. Gợi ý thêm: Mì Xào Chay.', N'{"sources":[{"type":"RECIPE","id":10130,"title":"Mì Xào Chay – bản giảm cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10130,"title":"Mì Xào Chay – bản giảm cân","cookTimeMinutes":29}]}', DATEADD(MINUTE,-81610,@Now)),
(10343, 10037, 'USER', N'Mình nên ăn bao nhiêu calo mỗi ngày?', NULL, DATEADD(MINUTE,-81604,@Now)),
(10344, 10037, 'ASSISTANT', N'Con số phụ thuộc vào chiều cao, cân nặng, tuổi và mục tiêu. Bạn có thể xem mức calo mục tiêu trong hồ sơ sức khỏe; hệ thống tính từ BMR và hệ số vận động của bạn.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-81603,@Now)),
(10345, 10037, 'USER', N'Đậu hũ và tempeh khác nhau thế nào?', NULL, DATEADD(MINUTE,-81600,@Now)),
(10346, 10037, 'ASSISTANT', N'Đậu hũ làm từ sữa đậu nành đông tụ, mềm và nhẹ. Tempeh làm từ đậu nành lên men nên đặc, nhiều chất xơ và có vị bùi, thường giàu đạm hơn trên cùng khối lượng. Gợi ý thêm: Chả Lá Lốt Chay Đơn Giản.', N'{"sources":[{"type":"RECIPE","id":10165,"title":"Chả Lá Lốt Chay Đơn Giản – bản tăng cân (không hành tỏi)"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10165,"title":"Chả Lá Lốt Chay Đơn Giản – bản tăng cân (không hành tỏi)","cookTimeMinutes":36}]}', DATEADD(MINUTE,-81599,@Now)),
