(10793, 10087, 'USER', N'Đậu hũ và tempeh khác nhau thế nào?', NULL, DATEADD(MINUTE,-721,@Now)),
(10794, 10087, 'ASSISTANT', N'Đậu hũ làm từ sữa đậu nành đông tụ, mềm và nhẹ. Tempeh làm từ đậu nành lên men nên đặc, nhiều chất xơ và có vị bùi, thường giàu đạm hơn trên cùng khối lượng. Gợi ý thêm: Hủ Tíu Xào Chay Vị Me.', N'{"sources":[{"type":"RECIPE","id":10134,"title":"Hủ Tíu Xào Chay Vị Me – bản giữ cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10134,"title":"Hủ Tíu Xào Chay Vị Me – bản giữ cân","cookTimeMinutes":42}]}', DATEADD(MINUTE,-720,@Now)),
(10795, 10087, 'USER', N'Ăn chay trường có được ăn hành tỏi không?', NULL, DATEADD(MINUTE,-712,@Now)),
(10796, 10087, 'ASSISTANT', N'Theo trường phái Phật giáo, ngũ vị tân (hành, tỏi, hẹ, kiệu, boa-rô) thường được kiêng. Bạn có thể bật tùy chọn không ngũ vị tân để nhận công thức phù hợp.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-711,@Now)),
(10797, 10088, 'USER', N'Ăn chay trường có được ăn hành tỏi không?', NULL, DATEADD(MINUTE,-21679,@Now)),
(10798, 10088, 'ASSISTANT', N'Theo trường phái Phật giáo, ngũ vị tân (hành, tỏi, hẹ, kiệu, boa-rô) thường được kiêng. Bạn có thể bật tùy chọn không ngũ vị tân để nhận công thức phù hợp.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-21678,@Now)),
(10799, 10088, 'USER', N'Gợi ý thực đơn giảm cân cho một ngày ăn chay?', NULL, DATEADD(MINUTE,-21670,@Now)),
(10800, 10088, 'ASSISTANT', N'Bạn có thể ăn sáng với cháo yến mạch rau củ, trưa với cơm gạo lứt và đậu hũ sốt cà chua, tối với canh nấm rau củ. Tổng năng lượng nên bám theo mục tiêu calo trong hồ sơ của bạn.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-21669,@Now));
