(10852, 10094, 'ASSISTANT', N'Hãy tăng khẩu phần năng lượng bằng các món giàu đạm và chất béo tốt như đậu hũ chiên, tempeh, hạt, khoai lang, kết hợp tập luyện kháng lực và ăn thêm bữa phụ. Gợi ý thêm: Bò Bía Chay; Váng Đậu Xào Chay.', N'{"sources":[{"type":"RECIPE","id":10034,"title":"Bò Bía Chay – bản giữ cân"},{"type":"RECIPE","id":10075,"title":"Váng Đậu Xào Chay – bản giữ cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10034,"title":"Bò Bía Chay – bản giữ cân","cookTimeMinutes":31},{"recipeId":10075,"title":"Váng Đậu Xào Chay – bản giữ cân","cookTimeMinutes":36}]}', DATEADD(MINUTE,-2784,@Now)),
(10853, 10094, 'USER', N'Mình bị dị ứng đậu phộng thì nên tránh món nào?', NULL, DATEADD(MINUTE,-2779,@Now)),
(10854, 10094, 'ASSISTANT', N'Bạn nên tránh các món có đậu phộng rang, bơ đậu phộng, nước chấm có lạc và kiểm tra nhãn sản phẩm. Hãy khai báo dị ứng trong hồ sơ để hệ thống lọc công thức phù hợp.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-2778,@Now)),
(10855, 10095, 'USER', N'Gợi ý thực đơn giảm cân cho một ngày ăn chay?', NULL, DATEADD(MINUTE,-795,@Now)),
(10856, 10095, 'ASSISTANT', N'Bạn có thể ăn sáng với cháo yến mạch rau củ, trưa với cơm gạo lứt và đậu hũ sốt cà chua, tối với canh nấm rau củ. Tổng năng lượng nên bám theo mục tiêu calo trong hồ sơ của bạn. Gợi ý thêm: Rau Xào Thập Cẩm.', N'{"sources":[{"type":"RECIPE","id":10163,"title":"Rau Xào Thập Cẩm – bản giữ cân (không hành tỏi)"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10163,"title":"Rau Xào Thập Cẩm – bản giữ cân (không hành tỏi)","cookTimeMinutes":26}]}', DATEADD(MINUTE,-794,@Now)),
(10857, 10095, 'USER', N'Mình nên ăn bao nhiêu calo mỗi ngày?', NULL, DATEADD(MINUTE,-791,@Now)),
(10858, 10095, 'ASSISTANT', N'Con số phụ thuộc vào chiều cao, cân nặng, tuổi và mục tiêu. Bạn có thể xem mức calo mục tiêu trong hồ sơ sức khỏe; hệ thống tính từ BMR và hệ số vận động của bạn. Gợi ý thêm: Bánh Bột Lọc Chay; Rau Củ Kho Chay.', N'{"sources":[{"type":"RECIPE","id":10152,"title":"Bánh Bột Lọc Chay – bản giữ cân"},{"type":"RECIPE","id":10020,"title":"Rau Củ Kho Chay – bản giữ cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10152,"title":"Bánh Bột Lọc Chay – bản giữ cân","cookTimeMinutes":34},{"recipeId":10020,"title":"Rau Củ Kho Chay – bản giữ cân","cookTimeMinutes":33}]}', DATEADD(MINUTE,-790,@Now)),
(10859, 10095, 'USER', N'Đậu hũ và tempeh khác nhau thế nào?', NULL, DATEADD(MINUTE,-786,@Now)),
(10860, 10095, 'ASSISTANT', N'Đậu hũ làm từ sữa đậu nành đông tụ, mềm và nhẹ. Tempeh làm từ đậu nành lên men nên đặc, nhiều chất xơ và có vị bùi, thường giàu đạm hơn trên cùng khối lượng. Gợi ý thêm: Khổ Qua Kho Chay; Đậu Phụ Chua Ngọt.', N'{"sources":[{"type":"RECIPE","id":10164,"title":"Khổ Qua Kho Chay – bản giữ cân (không hành tỏi)"},{"type":"RECIPE","id":10007,"title":"Đậu Phụ Chua Ngọt – bản giữ cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10164,"title":"Khổ Qua Kho Chay – bản giữ cân (không hành tỏi)","cookTimeMinutes":34},{"recipeId":10007,"title":"Đậu Phụ Chua Ngọt – bản giữ cân","cookTimeMinutes":36}]}', DATEADD(MINUTE,-785,@Now)),
