(11201, 10133, 'USER', N'Mình nên ăn bao nhiêu calo mỗi ngày?', NULL, DATEADD(MINUTE,-8772,@Now)),
(11202, 10133, 'ASSISTANT', N'Con số phụ thuộc vào chiều cao, cân nặng, tuổi và mục tiêu. Bạn có thể xem mức calo mục tiêu trong hồ sơ sức khỏe; hệ thống tính từ BMR và hệ số vận động của bạn.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-8771,@Now)),
(11203, 10133, 'USER', N'Mình bị dị ứng đậu phộng thì nên tránh món nào?', NULL, DATEADD(MINUTE,-8770,@Now)),
(11204, 10133, 'ASSISTANT', N'Bạn nên tránh các món có đậu phộng rang, bơ đậu phộng, nước chấm có lạc và kiểm tra nhãn sản phẩm. Hãy khai báo dị ứng trong hồ sơ để hệ thống lọc công thức phù hợp.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-8769,@Now)),
(11205, 10133, 'USER', N'Ăn chay trường có được ăn hành tỏi không?', NULL, DATEADD(MINUTE,-8764,@Now)),
(11206, 10133, 'ASSISTANT', N'Theo trường phái Phật giáo, ngũ vị tân (hành, tỏi, hẹ, kiệu, boa-rô) thường được kiêng. Bạn có thể bật tùy chọn không ngũ vị tân để nhận công thức phù hợp.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-8763,@Now)),
(11207, 10133, 'USER', N'Tăng cân khi ăn chay bằng cách nào?', NULL, DATEADD(MINUTE,-8758,@Now)),
(11208, 10133, 'ASSISTANT', N'Hãy tăng khẩu phần năng lượng bằng các món giàu đạm và chất béo tốt như đậu hũ chiên, tempeh, hạt, khoai lang, kết hợp tập luyện kháng lực và ăn thêm bữa phụ.', N'{"sources":[],"ragUsed":false,"recommendedRecipes":[]}', DATEADD(MINUTE,-8757,@Now)),
(11209, 10134, 'USER', N'Đậu hũ và tempeh khác nhau thế nào?', NULL, DATEADD(MINUTE,-4889,@Now)),
(11210, 10134, 'ASSISTANT', N'Đậu hũ làm từ sữa đậu nành đông tụ, mềm và nhẹ. Tempeh làm từ đậu nành lên men nên đặc, nhiều chất xơ và có vị bùi, thường giàu đạm hơn trên cùng khối lượng. Gợi ý thêm: Đậu Phụ Cay Sốt Nấm.', N'{"sources":[{"type":"RECIPE","id":10091,"title":"Đậu Phụ Cay Sốt Nấm – bản tăng cân"}],"ragUsed":true,"recommendedRecipes":[{"recipeId":10091,"title":"Đậu Phụ Cay Sốt Nấm – bản tăng cân","cookTimeMinutes":39}]}', DATEADD(MINUTE,-4888,@Now)),
(11211, 10134, 'USER', N'Tăng cân khi ăn chay bằng cách nào?', NULL, DATEADD(MINUTE,-4884,@Now)),
